  'Rod: ' + a('https://www.practical-sailor.com/systems-propulsion/steady-at-the-helm/','Practical Sailor, steady at the helm') + ', ' + a('https://www.boats.com/reviews/whitlock-mamba-drives/','boats.com on the Mamba') + ', ' + a('https://www.lewmar.com/cobra-steering','Lewmar Cobra page') + '; wear points and spares from ' + a('https://forums.ybw.com/threads/whitlock-cobra-repairs-and-maintenance.515955/','YBW threads') + ' (anecdotal) and ' + a('https://yachtsteeringservices.com/product-category/whitlock-lewmar-steering/','Yacht Steering Services') + '.',
  'Hydraulic: ' + a('https://vetus.com/wp-content/uploads/020105.03-r05-2022-01-MTC30_175.pdf','Vetus installation manual') + ', ' + a('https://www.vetus-shop.com/files/Vetus_Filling_Bleeding.pdf','Vetus filling and bleeding') + ', ' + a('https://www.boats.net/blog/troubleshooting-hydraulic-steering-system-problems','boats.net on hydraulic faults') + '.',
